import React, { useState, useEffect } from 'react';
import './InfoSection.css';

export const InfoSection = ({ title, data, onDataChange }) => {
  const [formData, setFormData] = useState(data);

  useEffect(() => {
    setFormData(data);
  }, [data]);

  const handleInputChange = (field, value) => {
    const newData = {
      ...formData,
      [field]: value
    };
    setFormData(newData);
    
    // Only call onDataChange if it's provided
    if (typeof onDataChange === 'function') {
      onDataChange(newData);
    }
  };

  const renderFields = () => {
    if (!formData) return null;

    const formatFieldName = (field) => {
      // Handle special cases
      const specialCases = {
        'NPI': 'NPI',
        'TAX ID': 'Tax ID',
        'EFTNUMBER': 'EFT Number',
        'CHECKNUMBER': 'Check Number',
        'ZIPCODE': 'Zip Code',
        'PHONENUMBER': 'Phone Number'
      };

      if (specialCases[field]) {
        return specialCases[field];
      }

      // For other fields, add spaces between words and capitalize each word
      return field
        .replace(/_/g, ' ')
        .split(' ')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');
    };

    return Object.entries(formData)
      .filter(([field, value]) => {
        // Only show EFTNUMBER or CHECKNUMBER if they have a value
        if (field === 'EFTNUMBER' || field === 'CHECKNUMBER') {
          return value !== null && value !== undefined && value !== '';
        }
        return true;
      })
      .map(([field, value]) => (
        <div key={field} className="form-group">
          <label>{formatFieldName(field)}</label>
          <input
            type={typeof value === 'number' ? 'number' : 'text'}
            value={value || ''}
            onChange={(e) => handleInputChange(field, e.target.value)}
          />
        </div>
      ));
  };

  return (
    <div className="info-section">
      <h3 className="section-title">{title}</h3>
      {renderFields()}
    </div>
  );
}; 