import React, { useState, useEffect } from 'react';
import { StatsSection } from './StatsSection';
import { ClaimSection } from './ClaimSection';
import { InfoSection } from './InfoSection';
import { LoadingOverlay } from './LoadingOverlay';
import './FormContainer.css';

export const FormContainer = ({ jsonData, onConvert, file, onDataUpdate }) => {
  const [loading, setLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('Processing document...');
  const [localJsonData, setLocalJsonData] = useState(jsonData);
  const [selectedFile, setSelectedFile] = useState(file);

  useEffect(() => {
    setLocalJsonData(jsonData);
  }, [jsonData]);

  if (!localJsonData) return null;

  const handlePayerInfoChange = (updatedData) => {
    const updatedJsonData = {
      ...localJsonData,
      PayerInfo: updatedData
    };
    setLocalJsonData(updatedJsonData);
    if (typeof onDataUpdate === 'function') {
      onDataUpdate(updatedJsonData);
    }
  };

  const handlePracticeInfoChange = (updatedData) => {
    const updatedJsonData = {
      ...localJsonData,
      PracticeInfo: updatedData
    };
    setLocalJsonData(updatedJsonData);
    if (typeof onDataUpdate === 'function') {
      onDataUpdate(updatedJsonData);
    }
  };

  const handleClaimsUpdate = (updatedClaims) => {
    const updatedJsonData = {
      ...localJsonData,
      Claims: updatedClaims
    };
    setLocalJsonData(updatedJsonData);
    if (typeof onDataUpdate === 'function') {
      onDataUpdate(updatedJsonData);
    }
  };

  const handlePostData = async () => {
    try {
      // Validate reason codes before posting
      const formatRegex = /^[A-Z]{1,2}-\d{1,2}$/;
      const invalidFields = [];

      localJsonData.Claims.forEach((claim, claimIndex) => {
        claim.SERVICES?.forEach((service, serviceIndex) => {
          service.ADJUSTMENTCODES?.forEach((code, codeIndex) => {
            const value = `${code.GROUPCODE}-${code.CODE}`;
            if (!value || value === '-' || !formatRegex.test(value)) {
              invalidFields.push(`Claim ${claimIndex + 1}, Service ${serviceIndex + 1}, Code ${codeIndex + 1}: "${value || '(empty)'}"`);
            }
          });
        });
      });

      if (invalidFields.length > 0) {
        alert(`Invalid reason code format in the following fields:\n\n${invalidFields.join('\n')}\n\nPlease correct these fields before posting. Reason codes must contain 1-2 uppercase letters followed by a hyphen and 1-2 digits (e.g., "A-1" or "AB-12").`);
        return;
      }

      // Get the JWT token from localStorage
      const token = localStorage.getItem('jwt_token');
      token = '';
      if (!token) {
        console.error('No authentication token found');
        return;
      }

      // Create FormData object to send both file and JSON data
      const formData = new FormData();
      if (selectedFile) {
        formData.append('file', selectedFile);
      }
      formData.append('jsonData', JSON.stringify(localJsonData));

      console.log('Sending file:', selectedFile);
      console.log('Sending JSON data:', localJsonData);

      // Send the data to the API
      const response = await fetch('http://localhost:8002/api/Payment/SaveEOBPayment', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`
        },
        body: formData
      });

      if (!response.ok) {
        throw new Error('Failed to post data');
      }

      const result = await response.json();
      console.log('API Response:', result);
      alert('Data posted successfully!');
    } catch (error) {
      console.error('Error posting data:', error);
      alert('Failed to post data. Please try again.');
    }
  };

  return (
    <div className="form-container">
      <div className="form-header">
        <h2>Extracted Data:</h2>
        <div className="button-group">
          <button 
            className="post-button" 
            onClick={handlePostData}
            disabled={loading}
          >
            Post Data
          </button>
          <button 
            className="convert-button" 
            onClick={onConvert}
            disabled={loading}
          >
            Convert to ERA
          </button>
        </div>
      </div>
      <StatsSection jsonData={localJsonData} />
      <div className="main-section">
        {localJsonData.PayerInfo && (
          <InfoSection 
            title="Payer Information" 
            data={localJsonData.PayerInfo} 
            onDataChange={handlePayerInfoChange}
          />
        )}
        {localJsonData.PracticeInfo && (
          <InfoSection 
            title="Practice Information" 
            data={localJsonData.PracticeInfo} 
            onDataChange={handlePracticeInfoChange}
          />
        )}
        {localJsonData.Claims && (
          <ClaimSection 
            claims={localJsonData.Claims} 
            onClaimUpdate={handleClaimsUpdate}
          />
        )}
      </div>
      <LoadingOverlay show={loading} message={loadingMessage} />
    </div>
  );
};