import React from 'react';
import './StatsSection.css';

export const StatsSection = ({ jsonData }) => {
  const calculateStats = () => {
    const totalClaims = jsonData.Claims ? jsonData.Claims.length : 0;
    const totalServices = jsonData.Claims ? jsonData.Claims.reduce((sum, claim) => sum + claim.SERVICES.length, 0) : 0;
    const totalBilled = jsonData.Claims ? jsonData.Claims.reduce((sum, claim) => 
      sum + claim.SERVICES.reduce((serviceSum, service) => serviceSum + (parseFloat(service.BILLEDAMOUNT.toString().replace(',','')) || 0), 0), 0) : 0;
    const totalAllowed = jsonData.Claims ? jsonData.Claims.reduce((sum, claim) => 
      sum + claim.SERVICES.reduce((serviceSum, service) => serviceSum + (parseFloat(service.ALLOWEDAMOUNT.toString().replace(',','')) || 0), 0), 0) : 0;
    const totalPaid = jsonData.Claims ? jsonData.Claims.reduce((sum, claim) => 
      sum + claim.SERVICES.reduce((serviceSum, service) => serviceSum + (parseFloat(service.PROVIDERPAID.toString().replace(',','')) || 0), 0), 0) : 0;
    const totalPatientResponsibility = jsonData.Claims ? jsonData.Claims.reduce((sum, claim) => 
      sum + (parseFloat(claim.PATIENTRESP) || 0), 0) : 0;

    return [
      { label: 'Total Claims', value: totalClaims },
      { label: 'Total Services', value: totalServices },
      { label: 'Total Billed Amount', value: `$${totalBilled.toFixed(2)}` },
      { label: 'Total Allowed Amount', value: `$${totalAllowed.toFixed(2)}` },
      { label: 'Total Paid Amount', value: `$${totalPaid.toFixed(2)}` },
      { label: 'Total Patient Responsibility', value: `$${totalPatientResponsibility.toFixed(2)}` }
    ];
  };

  const stats = calculateStats();

  return (
    <div className="stats-section">
      <div className="stats-grid">
        {stats.map((stat, index) => (
          <div key={index} className="stat-item">
            <div className="stat-label">{stat.label}</div>
            <div className="stat-value">{stat.value}</div>
          </div>
        ))}
      </div>
    </div>
  );
}; 