import React from 'react';
import { UploadSection } from './components/UploadSection';
import { ContentWrapper } from './components/ContentWrapper';
import { LoadingOverlay } from './components/LoadingOverlay';
import './App.css';

function App() {
  const [loading, setLoading] = React.useState(false);
  const [jsonData, setJsonData] = React.useState(null);
  const [currentFile, setCurrentFile] = React.useState(null);
  const [error, setError] = React.useState(null);

  const handleFileUpload = async (file) => {
    setCurrentFile(file);
    setLoading(true);
    setJsonData(null);

    try {
      const formData = new FormData();
      formData.append("file", file);

      // Update this URL to match your backend API endpoint
      const response = await fetch('http://localhost:5000/api/extract-text', {
        method: 'POST',
        body: formData
      });

      if (response.ok) {
        const responseData = await response.json();
        setJsonData(responseData.data || responseData);
      } else {
        alert("Error processing the file.");
      }
    } catch (error) {
      console.error("Error:", error);
      alert("Error uploading the file.");
    } finally {
      setLoading(false);
    }
  };

  const handleDataUpdate = (updatedData) => {
    setJsonData(updatedData);
  };

  const handleConvert = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('http://127.0.0.1:5000/convert_eob_to_era', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(jsonData)
      });

      if (!response.ok) {
        throw new Error('Failed to generate ERA file');
      }

      const blob = await response.blob();
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = 'era_file.txt'; // Filename for the downloaded file
      link.click();
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="App">
      <UploadSection onFileUpload={handleFileUpload} />
      <ContentWrapper jsonData={jsonData} file={currentFile} onConvert={handleConvert} />
      <LoadingOverlay show={loading} />
      {error && <div className="error-message">{error}</div>}
    </div>
  );
}

export default App;