import React, { useState, useEffect } from 'react';
import './ClaimSection.css';

export const ClaimSection = ({ claims, onClaimUpdate }) => {
  const [localClaims, setLocalClaims] = useState(claims);
  const [inputValues, setInputValues] = useState({});

  // Update local claims when props change
  useEffect(() => {
    setLocalClaims(claims);
    // Initialize input values
    const newInputValues = {};
    claims.forEach((claim, claimIndex) => {
      claim.SERVICES?.forEach((service, serviceIndex) => {
        service.ADJUSTMENTCODES?.forEach((code, codeIndex) => {
          const key = `${claimIndex}-${serviceIndex}-${codeIndex}`;
          // Only set the value if both GROUPCODE and CODE exist
          if (code.GROUPCODE && code.CODE) {
            newInputValues[key] = `${code.GROUPCODE}-${code.CODE}`;
          } else {
            newInputValues[key] = '';
          }
        });
      });
    });
    setInputValues(newInputValues);
  }, [claims]);

  const handleStatusChange = async (claimIndex, newStatusCode) => {
    try {
      // Update local state immediately
      const updatedClaims = [...localClaims];
      updatedClaims[claimIndex] = {
        ...updatedClaims[claimIndex],
        STATUSCODE: newStatusCode
      };
      setLocalClaims(updatedClaims);

      // Get the JWT token from localStorage
      const token = localStorage.getItem('jwt_token');
      if (!token) {
        console.error('No authentication token found');
        return;
      }

      // Create the request payload
      const payload = {
        claimIndex,
        statusCode: newStatusCode
      };

      // Send the update to the API
      const response = await fetch('http://localhost:8002/api/Payment/UpdateClaimStatus', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        // Revert the change if the API call fails
        setLocalClaims(claims);
        throw new Error('Failed to update status code');
      }

      // Update parent component after successful API call
      if (onClaimUpdate) {
        onClaimUpdate(updatedClaims);
      }
    } catch (error) {
      console.error('Error updating status code:', error);
      alert('Failed to update status code. Please try again.');
    }
  };

  const handleReasonCodeChange = (claimIndex, serviceIndex, codeIndex, newValue) => {
    const key = `${claimIndex}-${serviceIndex}-${codeIndex}`;
    
    // If the value is empty or just a hyphen, set it to empty string
    if (!newValue || newValue === '-') {
      setInputValues(prev => ({
        ...prev,
        [key]: ''
      }));
      return;
    }
    
    // Convert to uppercase
    const upperValue = newValue.toUpperCase();
    
    // Update input value immediately to allow typing
    setInputValues(prev => ({
      ...prev,
      [key]: upperValue
    }));
  };

  const handlePostData = (claimIndex, serviceIndex, codeIndex) => {
    const key = `${claimIndex}-${serviceIndex}-${codeIndex}`;
    const value = inputValues[key];

    // Update local state
    const updatedClaims = [...localClaims];
    
    // Handle empty value
    if (!value || value === '-') {
      updatedClaims[claimIndex].SERVICES[serviceIndex].ADJUSTMENTCODES[codeIndex] = {
        ...updatedClaims[claimIndex].SERVICES[serviceIndex].ADJUSTMENTCODES[codeIndex],
        GROUPCODE: '',
        CODE: ''
      };
      // Clear the input value
      setInputValues(prev => ({
        ...prev,
        [key]: ''
      }));
    } else {
      const [groupCode, code] = value.split('-');
      updatedClaims[claimIndex].SERVICES[serviceIndex].ADJUSTMENTCODES[codeIndex] = {
        ...updatedClaims[claimIndex].SERVICES[serviceIndex].ADJUSTMENTCODES[codeIndex],
        GROUPCODE: groupCode || '',
        CODE: code || ''
      };
    }
    
    setLocalClaims(updatedClaims);

    // Update parent component
    if (onClaimUpdate) {
      onClaimUpdate(updatedClaims);
    }
  };

  const renderServiceTable = (services) => {
    const serviceHeaders = [
      'REND PROV', 'SERV DATE', 'POS', 'NOS', 'PROC', 'MODS',
      'BILLED', 'ALLOWED', 'COPAY', 'DEDUCT', 'COINS', 'GRP/RC-AMT', 'PROV PD'
    ];

    const calculateTotals = (services) => ({
      BILLED: services.reduce((sum, service) => sum + (parseFloat(service.BILLEDAMOUNT.toString().replace(',','')) || 0), 0),
      ALLOWED: services.reduce((sum, service) => sum + (parseFloat(service.ALLOWEDAMOUNT.toString().replace(',','')) || 0), 0),
      COPAY: services.reduce((sum, service) => sum + (parseFloat(service.COPAYAMOUNT.toString().replace(',','')) || 0), 0),
      DEDUCT: services.reduce((sum, service) => sum + (parseFloat(service.DEDUCTIBLEAMOUNT.toString().replace(',','')) || 0), 0),
      COINSURANCE: services.reduce((sum, service) => sum + (parseFloat(service.COINSURANCEAMOUNT.toString().replace(',','')) || 0), 0),
      PROVIDERPAID: services.reduce((sum, service) => sum + (parseFloat(service.PROVIDERPAID.toString().replace(',','')) || 0), 0),
      ADJUSTMENTCODES: services.reduce((sum, service) => 
        sum + (Array.isArray(service.ADJUSTMENTCODES) 
          ? service.ADJUSTMENTCODES.reduce((codeSum, code) => codeSum + (parseFloat(code.AMOUNT.toString().replace(',','')) || 0), 0)
          : 0), 0)
    });

    const totals = calculateTotals(services);

    return (
      <table className="service-line-table">
        <thead>
          <tr>
            {serviceHeaders.map((header, index) => (
              <th key={index}>{header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {services.map((service, serviceIndex) => (
            <tr key={serviceIndex}>
              <td>{service.RENDERPROVIDERNPI || ''}</td>
              <td>{`${service.SERVICEFROMDATE} ${service.SERVICETODATE || ''}`}</td>
              <td>{service.POS || ''}</td>
              <td>{service.NOS || ''}</td>
              <td>{service.PROCCODE || ''}</td>
              <td>{Array.isArray(service.MODIFIERS) ? service.MODIFIERS.join(' ') : service.MODIFIERS || ''}</td>
              <td>{parseFloat(service.BILLEDAMOUNT.toString().replace(',','')).toFixed(2)}</td>
              <td>{parseFloat(service.ALLOWEDAMOUNT.toString().replace(',','')).toFixed(2)}</td>
              <td>{parseFloat(service.COPAYAMOUNT.toString().replace(',','')).toFixed(2)}</td>
              <td>{parseFloat(service.DEDUCTIBLEAMOUNT.toString().replace(',','')).toFixed(2)}</td>
              <td>{parseFloat(service.COINSURANCEAMOUNT.toString().replace(',','')).toFixed(2)}</td>
              <td>
                {service.ADJUSTMENTCODES && service.ADJUSTMENTCODES.length > 0 && (
                  <table className="reason-codes-table">
                    <tbody>
                      {service.ADJUSTMENTCODES.map((code, codeIndex) => {
                        const claimIndex = localClaims.findIndex(claim => 
                          claim.SERVICES.some(s => s === service)
                        );
                        const key = `${claimIndex}-${serviceIndex}-${codeIndex}`;
                        return (
                          <tr key={codeIndex}>
                            <td>
                              <input 
                                type="text" 
                                value={inputValues[key] || ''}
                                onChange={(e) => {
                                  handleReasonCodeChange(
                                    claimIndex,
                                    serviceIndex,
                                    codeIndex,
                                    e.target.value
                                  );
                                }}
                                onBlur={() => handlePostData(
                                  claimIndex,
                                  serviceIndex,
                                  codeIndex
                                )}
                                className="reason-code-input"
                                placeholder="XX-XX"
                              />
                            </td>
                            <td>{code.AMOUNT}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                )}
              </td>
              <td>{service.PROVIDERPAID}</td>
            </tr>
          ))}
          <tr className="total-row">
            <td colSpan="6">TOTAL</td>
            <td>{totals.BILLED.toFixed(2)}</td>
            <td>{totals.ALLOWED.toFixed(2)}</td>
            <td>{totals.COPAY.toFixed(2)}</td>
            <td>{totals.DEDUCT.toFixed(2)}</td>
            <td>{totals.COINSURANCE.toFixed(2)}</td>
            <td>{totals.ADJUSTMENTCODES.toFixed(2)}</td>
            <td>{totals.PROVIDERPAID.toFixed(2)}</td>
          </tr>
        </tbody>
      </table>
    );
  };

  const renderProviderAdjustmentTable = (adjustments) => {
    if (!adjustments || adjustments.length === 0) return null;

    return (
      <div className="provider-adjustment-section">
        <h4>Provider Adjustment Details</h4>
        <table className="provider-adjustment-table">
          <thead>
            <tr>
              <th>Reason Code</th>
              <th>Identifier</th>
              <th>Amount</th>
            </tr>
          </thead>
          <tbody>
            {adjustments.map((adj, index) => (
              <tr key={index}>
                <td>{adj.REASONCODE}</td>
                <td>{adj.IDENTIFIER}</td>
                <td className={adj.AMOUNT < 0 ? 'negative-amount' : ''}>
                  {adj.AMOUNT.toFixed(2)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div className="claims-section">
      {localClaims.map((claim, index) => (
        <div key={index} className="claim-block">
          <div className="claim-info">
            <div className="claim-header">
              Claim #{index + 1}
            </div>
            <div className="claim-details">
              NAME: {claim.NAME || ''} &nbsp;
              INSURED NAME: {claim.INSUREDNAME || ''} &nbsp;
              HIC: {claim.HIC || ''} &nbsp;
              ACNT: {claim.CLAIMNUMBER || ''} &nbsp;
              ICN: {claim.ICN || ''} &nbsp;
              ASG: {claim.ASG || ''} &nbsp;
              MOA: {claim.MOA || ''}
            </div>
          </div>

          {claim.SERVICES && claim.SERVICES.length > 0 && renderServiceTable(claim.SERVICES)}

          <div className="claim-summary">
            <div className="summary-row">
              <span>PT RESP: {claim.PATIENTRESP}</span>
              <span>ADJ TO TOTAL: {claim.ADJTOTOTAL}</span>
              <span>INTEREST: {claim.INTEREST}</span>
              <span>LATE FILING CHARGE: {claim.LATEFILINGCHARGE}</span>
              <span>NET: {claim.NET}</span>
            </div>
            <div className="plan-type">PLAN TYPE: {claim.PLANTYPE || ''}</div>
            <div className="status-code">
              STATUS CODE: 
              <select 
                value={claim.STATUSCODE || ''} 
                onChange={(e) => handleStatusChange(index, e.target.value)}
                className="status-code-select"
              >
                <option value="1">(1)-Processed as Primary</option>
                <option value="2">(1)-Processed as Secondary</option>
                <option value="3">(2)-Processed as Tertiary</option>
                <option value="4">(3)-Denied</option>
                <option value="19">(19)-Processed as Primary, Forwarded to Additional Payer(s)</option>
                <option value="20">(20)-Processed as Secondary, Forwarded to Additional Payer(s)</option>
                <option value="21">(21)-Processed as Tertiary, Forwarded to Additional Payer(s)</option>
                <option value="22">(22)-Reversal of Previous Payment</option>
                <option value="23">(23)-Not Our Claim, Forwarded to Additional Payer(s)</option>
                <option value="25">(25)-Predetermination Pricing Only - No Payment</option>
              </select>
            </div>
            {claim.CLAIMINFOFORWARDEDTO && (
              <div className="forwarded-info">
                <span className="forwarded-label">Claim Forwarded To:</span>
                <span className="forwarded-value">{claim.CLAIMINFOFORWARDEDTO}</span>
              </div>
            )}
            {claim.PROVIDERADJDETAILS && renderProviderAdjustmentTable(claim.PROVIDERADJDETAILS)}
          </div>
        </div>
      ))}
    </div>
  );
}; 