import React, { useState, useEffect, useRef } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import './PreviewContainer.css';

// Set the worker source to a CDN version that matches your pdfjs-dist version
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

export const PreviewContainer = ({ file }) => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [currentZoom, setCurrentZoom] = useState(1);
  const [translateX, setTranslateX] = useState(0);
  const [translateY, setTranslateY] = useState(0);
  const [currentPdfDoc, setCurrentPdfDoc] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageCount, setPageCount] = useState(1);
  const [scale, setScale] = useState(1.0);
  const [isMoving, setIsMoving] = useState(false);
  const [previewUrl, setPreviewUrl] = useState('');
  const [isImage, setIsImage] = useState(false);
  const [error, setError] = useState(null);
  const moveInterval = useRef(null);
  const imagePreviewRef = useRef(null);
  const pdfViewerRef = useRef(null);

  useEffect(() => {
    if (file) {
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
      setError(null);

      if (file.type === 'application/pdf') {
        setIsImage(false);
        loadPDF(url);
      } else if (file.type.startsWith('image/')) {
        setIsImage(true);
        setCurrentPdfDoc(null);
        if (imagePreviewRef.current) {
          imagePreviewRef.current.style.display = 'block';
        }
        if (pdfViewerRef.current) {
          pdfViewerRef.current.style.display = 'none';
        }
      }

      return () => {
        URL.revokeObjectURL(url);
      };
    }
  }, [file]);

  const loadPDF = async (url) => {
    try {
      // First, fetch the PDF file as an ArrayBuffer
      const response = await fetch(url);
      const arrayBuffer = await response.arrayBuffer();

      const loadingTask = pdfjsLib.getDocument({
        data: arrayBuffer,
        cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/cmaps/',
        cMapPacked: true,
      });
      
      const pdfDoc = await loadingTask.promise;
      setCurrentPdfDoc(pdfDoc);
      setPageCount(pdfDoc.numPages);
      setCurrentPage(1);
      
      // Ensure canvas is visible before rendering
      if (pdfViewerRef.current) {
        pdfViewerRef.current.style.display = 'block';
      }
      if (imagePreviewRef.current) {
        imagePreviewRef.current.style.display = 'none';
      }

      // Render the first page immediately
      const page = await pdfDoc.getPage(1);
      const viewport = page.getViewport({ scale: 1.0 });
      const canvas = pdfViewerRef.current;
      const context = canvas.getContext('2d');
      
      canvas.height = viewport.height;
      canvas.width = viewport.width;

      const renderContext = {
        canvasContext: context,
        viewport: viewport
      };

      await page.render(renderContext).promise;
    } catch (error) {
      console.error('Error loading PDF:', error);
      setError('Error loading PDF file. Please try again.');
      // Hide PDF viewer and show error message
      if (pdfViewerRef.current) {
        pdfViewerRef.current.style.display = 'none';
      }
    }
  };

  const renderPage = async (num) => {
    if (!currentPdfDoc) return;

    try {
      const page = await currentPdfDoc.getPage(num);
      const viewport = page.getViewport({ scale });
      const canvas = pdfViewerRef.current;
      const context = canvas.getContext('2d');
      
      canvas.height = viewport.height;
      canvas.width = viewport.width;

      const renderContext = {
        canvasContext: context,
        viewport: viewport
      };

      await page.render(renderContext).promise;
    } catch (error) {
      console.error('Error rendering page:', error);
    }
  };

  const prevPage = () => {
    if (currentPage > 1) {
      const newPage = currentPage - 1;
      setCurrentPage(newPage);
      renderPage(newPage);
    }
  };

  const nextPage = () => {
    if (currentPage < pageCount) {
      const newPage = currentPage + 1;
      setCurrentPage(newPage);
      renderPage(newPage);
    }
  };

  const togglePreview = () => {
    setIsCollapsed(!isCollapsed);
  };

  const zoomImage = (factor) => {
    if (imagePreviewRef.current && imagePreviewRef.current.style.display !== 'none') {
      const newZoom = Math.max(0.5, Math.min(3, currentZoom * factor));
      setCurrentZoom(newZoom);
      
      if (newZoom <= 1) {
        setTranslateX(0);
        setTranslateY(0);
        stopMoving();
      } else {
        const zoomRatio = newZoom / currentZoom;
        setTranslateX(prev => prev * zoomRatio);
        setTranslateY(prev => prev * zoomRatio);
      }
    } else if (currentPdfDoc) {
      const newScale = Math.max(0.5, Math.min(3, scale * factor));
      setScale(newScale);
      renderPage(currentPage);
    }
  };

  const resetZoom = () => {
    setCurrentZoom(1);
    setScale(1.0);
    setTranslateX(0);
    setTranslateY(0);
    stopMoving();
    if (imagePreviewRef.current && imagePreviewRef.current.style.display !== 'none') {
      updateImageTransform();
    } else if (currentPdfDoc) {
      renderPage(currentPage);
    }
  };

  const startMoving = (e) => {
    if (currentZoom <= 1) return;
    
    setIsMoving(true);
    const rect = imagePreviewRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    
    const deltaX = e.clientX - centerX;
    const deltaY = e.clientY - centerY;
    
    if (moveInterval.current) {
      clearInterval(moveInterval.current);
    }
    
    moveInterval.current = setInterval(() => {
      if (!isMoving) return;
      
      const maxX = (currentZoom - 1) * imagePreviewRef.current.offsetWidth / 2;
      const maxY = (currentZoom - 1) * imagePreviewRef.current.offsetHeight / 2;
      
      setTranslateX(prev => {
        if (deltaX > 0) {
          return Math.min(prev + 20, maxX);
        }
        return Math.max(prev - 20, -maxX);
      });
      
      setTranslateY(prev => {
        if (deltaY > 0) {
          return Math.max(prev - 20, -maxY);
        }
        return Math.min(prev + 20, maxY);
      });
      
      updateImageTransform();
    }, 16);
  };

  const stopMoving = () => {
    setIsMoving(false);
    if (moveInterval.current) {
      clearInterval(moveInterval.current);
    }
  };

  const updateImageTransform = () => {
    if (imagePreviewRef.current && imagePreviewRef.current.style.display !== 'none') {
      imagePreviewRef.current.style.transform = `translate(${translateX}px, ${translateY}px) scale(${currentZoom})`;
    }
  };

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (currentZoom <= 1) return;
      
      const step = 20;
      switch(e.key) {
        case 'ArrowUp':
          setTranslateY(prev => Math.max(prev - step, -(currentZoom - 1) * imagePreviewRef.current.offsetHeight / 2));
          break;
        case 'ArrowDown':
          setTranslateY(prev => Math.min(prev + step, (currentZoom - 1) * imagePreviewRef.current.offsetHeight / 2));
          break;
        case 'ArrowLeft':
          setTranslateX(prev => Math.min(prev + step, (currentZoom - 1) * imagePreviewRef.current.offsetWidth / 2));
          break;
        case 'ArrowRight':
          setTranslateX(prev => Math.max(prev - step, -(currentZoom - 1) * imagePreviewRef.current.offsetWidth / 2));
          break;
        default:
          return;
      }
      updateImageTransform();
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [currentZoom]);

  return (
    <div className={`preview-container ${isCollapsed ? 'collapsed' : ''}`}>
      {file && (
        <button className="toggle-preview" onClick={togglePreview}>
          {isCollapsed ? '▶' : '◀'}
        </button>
      )}
      <div className="preview-wrapper">
        <img
          ref={imagePreviewRef}
          id="imagePreview"
          src={previewUrl}
          alt="Uploaded document preview"
          style={{ display: 'none' }}
          onMouseDown={startMoving}
        />
      </div>
      <canvas ref={pdfViewerRef} id="pdfViewer" style={{ display: 'none' }} />
      {error && <div className="error-message">{error}</div>}
      <div className="pdf-controls" style={{ display: currentPdfDoc && !isCollapsed ? 'flex' : 'none' }}>
        <button onClick={prevPage} disabled={currentPage <= 1}>Previous</button>
        <span className="page-info">
          Page {currentPage} of {pageCount}
        </span>
        <button onClick={nextPage} disabled={currentPage >= pageCount}>Next</button>
      </div>
      <div className="zoom-controls" style={{ display: isImage && !isCollapsed ? 'flex' : 'none' }}>
        <button onClick={() => zoomImage(1.2)}>Zoom In</button>
        <button onClick={() => zoomImage(0.8)}>Zoom Out</button>
        <button onClick={resetZoom}>Reset</button>
      </div>
    </div>
  );
}; 